package org.apache.commons.math3.distribution;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math3.exception.NotPositiveException;
import org.apache.commons.math3.exception.NotStrictlyPositiveException;
import org.apache.commons.math3.exception.NumberIsTooLargeException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.random.RandomGenerator;
import org.apache.commons.math3.random.Well19937c;
import org.apache.commons.math3.util.FastMath;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for HypergeometricDistribution.calculateNumericalVariance().
 * Since the method is protected, we use a subclass to expose it for testing or 
 * rely on the fact that tests in the same package can access protected members.
 */
public class HypergeometricDistribution_calculateNumericalVariance_TriageGen2Test {

    /**
     * Accessor subclass to test the protected method.
     */
    private static class TestableHypergeometricDistribution extends HypergeometricDistribution {
        public TestableHypergeometricDistribution(int populationSize, int numberOfSuccesses, int sampleSize) {
            super(populationSize, numberOfSuccesses, sampleSize);
        }

        @Override
        public double calculateNumericalVariance() {
            return super.calculateNumericalVariance();
        }
    }

    private static final double EPSILON = 1e-10;

    @Test
    public void testCalculateNumericalVariance_StandardCase() {
        // N=100, m=20, n=10
        // formula: (10 * 20 * (100 - 10) * (100 - 20)) / (100 * 100 * (100 - 1))
        // (10 * 20 * 90 * 80) / (100 * 100 * 99)
        // 1440000 / 990000 = 1.4545454545...
        int N = 100;
        int m = 20;
        int n = 10;
        double expected = (double) (n * m * (N - n) * (N - m)) / (N * N * (N - 1));

        TestableHypergeometricDistribution dist = new TestableHypergeometricDistribution(N, m, n);
        Assert.assertEquals(expected, dist.calculateNumericalVariance(), EPSILON);
    }

    @Test
    public void testCalculateNumericalVariance_ZeroSuccesses() {
        // If m = 0, variance should be 0
        int N = 100;
        int m = 0;
        int n = 10;

        TestableHypergeometricDistribution dist = new TestableHypergeometricDistribution(N, m, n);
        Assert.assertEquals(0.0, dist.calculateNumericalVariance(), EPSILON);
    }

    @Test
    public void testCalculateNumericalVariance_ZeroSampleSize() {
        // If n = 0, variance should be 0
        int N = 100;
        int m = 20;
        int n = 0;

        TestableHypergeometricDistribution dist = new TestableHypergeometricDistribution(N, m, n);
        Assert.assertEquals(0.0, dist.calculateNumericalVariance(), EPSILON);
    }

    @Test
    public void testCalculateNumericalVariance_AllSuccesses() {
        // If m = N, then (N - m) = 0, variance should be 0
        int N = 100;
        int m = 100;
        int n = 10;

        TestableHypergeometricDistribution dist = new TestableHypergeometricDistribution(N, m, n);
        Assert.assertEquals(0.0, dist.calculateNumericalVariance(), EPSILON);
    }

    @Test
    public void testCalculateNumericalVariance_SampleEqualsPopulation() {
        // If n = N, then (N - n) = 0, variance should be 0
        int N = 100;
        int m = 20;
        int n = 100;

        TestableHypergeometricDistribution dist = new TestableHypergeometricDistribution(N, m, n);
        Assert.assertEquals(0.0, dist.calculateNumericalVariance(), EPSILON);
    }

    @Test(expected = NotPositiveException.class)
    public void testConstructor_InvalidPopulationSize() {
        new TestableHypergeometricDistribution(0, 10, 5);
    }

    @Test
    public void testGettersMatchConstructor() {
        int N = 50;
        int m = 15;
        int n = 5;
        TestableHypergeometricDistribution dist = new TestableHypergeometricDistribution(N, m, n);

        Assert.assertEquals(N, dist.getPopulationSize());
        Assert.assertEquals(m, dist.getNumberOfSuccesses());
        Assert.assertEquals(n, dist.getSampleSize());
    }
}
